properties.query:
// Known malicious driver hashes
let sha256_hashes = dynamic([
    "bd1f381e5a3db22e88776b7873d4d2835e9a1ec620571d2b1da0c58f81c84a56",  // hlpdrv.sys
    "16f83f056177c4ec24c7e99d01ca9d9d6713bd0497eeedb777a3ffefa99c97f0"   // rwdrv.sys
]);

// Known malicious file paths (example values)
let file_paths = dynamic([
    @"\Users\REDACTED\AppData\Local\Temp\hlpdrv.sys",
    @"\Users\REDACTED\AppData\Local\Temp\rwdrv.sys"
]);

// Known malicious service names
let service_names = dynamic(["mgdsrv", "KMHLPSVC"]);

// FILE EVENTS: driver dropped onto disk
let fileEvents =
    DeviceFileEvents
    | where SHA256 in (sha256_hashes)
          or FolderPath has_any (file_paths)
    | project 
          TimeGenerated,
          DeviceName,
          FileName,
          FolderPath,
          SHA256,
          InitiatingProcessFileName,
          InitiatingProcessCommandLine,
          Source = "FileEvent";

// REGISTRY EVENTS: service creation (common BYOVD loading)
let regEvents =
    DeviceRegistryEvents
    | where RegistryKey has_any (
            @"SYSTEM\CurrentControlSet\Services\mgdsrv",
            @"SYSTEM\CurrentControlSet\Services\KMHLPSVC"
      )
    | project
          TimeGenerated,
          DeviceName,
          FileName = tostring(RegistryValueName),
          FolderPath = RegistryKey,
          SHA256 = "",
          InitiatingProcessFileName,
          InitiatingProcessCommandLine = tostring(RegistryValueData),
          Source = "RegistryEvent";

// PROCESS EVENTS: driver loading or suspicious service creation commands
let procEvents =
    DeviceProcessEvents
    | where ProcessCommandLine has_any ("hlpdrv.sys", "rwdrv.sys", "mgdsrv", "KMHLPSVC")
    | project
          TimeGenerated,
          DeviceName,
          FileName = InitiatingProcessFileName,
          FolderPath = "",
          SHA256 = "",
          InitiatingProcessFileName,
          InitiatingProcessCommandLine,
          Source = "ProcessEvent";

fileEvents
| union regEvents
| union procEvents

