properties.query:
// Detect Office app process execution with macro-related indicators
let OfficeApps = dynamic(["winword.exe","excel.exe","powerpnt.exe"]);
let OfficeDocExt = dynamic([".doc",".docx",".xls",".xlsx",".ppt",".pptx"]);
let MacroIndicators = dynamic(["vba","macro","/m","/x","/r","autoopen","auto_close","workbook_open"]);
DeviceProcessEvents
// Executable is an Office application
| where tolower(FileName) in (OfficeApps)
// Initiating (source) object appears to be an Office document
| where array_length(OfficeDocExt) == 0 or (tolower(InitiatingProcessFileName) has_any (OfficeDocExt))
// Macro-related indicators in the command line (case-insensitive)
| where tolower(ProcessCommandLine) has_any (MacroIndicators)
| project
    TimeGenerated,
    DeviceName,
    DeviceId,
    FileName,                          // Office app (winword/excel/powerpnt)
    ProcessCommandLine,
    InitiatingProcessAccountName,
    InitiatingProcessFileName,         // Document that initiated the process
    InitiatingProcessCommandLine,
    ReportId

